import{_ as t,a,o,a6 as d}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Locales","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/settings/locales/index.md","filePath":"api/graphql-api/admin/settings/locales/index.md","lastUpdated":1787725411000}'),l={name:"api/graphql-api/admin/settings/locales/index.md"};function r(n,e,s,i,c,h){return o(),a("div",null,e[0]||(e[0]=[d('<h1 id="locales" tabindex="-1">Locales <a class="header-anchor" href="#locales" aria-label="Permalink to &quot;Locales&quot;">​</a></h1><p>The Locales menu manages the storefront languages your store can offer. Each locale defines a language a channel can be served in — its <code>code</code>, display <code>name</code>, text <code>direction</code>, and an optional logo. It mirrors the admin <strong>Settings → Locales</strong> screen.</p><h2 id="what-a-locale-controls" tabindex="-1">What a locale controls <a class="header-anchor" href="#what-a-locale-controls" aria-label="Permalink to &quot;What a locale controls&quot;">​</a></h2><p>A locale is the set of language settings a storefront channel can switch to. A channel is assigned one or more locales and a default locale; shoppers can then browse the store in any of the channel&#39;s locales, with all translatable content (product names, CMS pages, category labels) shown in that language.</p><h2 id="when-a-row-appears-here" tabindex="-1">When a row appears here <a class="header-anchor" href="#when-a-row-appears-here" aria-label="Permalink to &quot;When a row appears here&quot;">​</a></h2><p>A row exists for every locale configured in the store. The store ships with seeded core locales (such as English) and you add more with the Create mutation. There is no automatic creation — locales appear only when seeded at install or added through this menu.</p><h2 id="field-meanings" tabindex="-1">Field meanings <a class="header-anchor" href="#field-meanings" aria-label="Permalink to &quot;Field meanings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>code</code></td><td>The locale code (e.g. <code>en</code>, <code>fr</code>, <code>pt-br</code>). Unique across the store.</td></tr><tr><td><code>name</code></td><td>Human-readable display name shown in the locale switcher.</td></tr><tr><td><code>direction</code></td><td>Text direction — <code>ltr</code> (left-to-right) or <code>rtl</code> (right-to-left, e.g. Arabic). Drives how the storefront lays out text when this locale is active.</td></tr><tr><td><code>logoPath</code></td><td>The stored relative path of the locale&#39;s flag/logo image, or <code>null</code> when none is set.</td></tr><tr><td><code>logoUrl</code></td><td>The fully-qualified public URL of that image, derived from <code>logoPath</code> — use this to display the logo. <code>null</code> when no logo is set.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>Timestamps. Seeded core locales may have <code>null</code> timestamps.</td></tr></tbody></table><h2 id="what-create-update-delete-do" tabindex="-1">What create / update / delete do <a class="header-anchor" href="#what-create-update-delete-do" aria-label="Permalink to &quot;What create / update / delete do&quot;">​</a></h2><ul><li><strong>Create</strong> adds a new locale (<code>code</code>, <code>name</code>, <code>direction</code>). A logo image cannot be uploaded over GraphQL, so new locales start without one.</li><li><strong>Update</strong> edits an existing locale; it is partial, so send only the fields you change alongside the <code>id</code>.</li><li><strong>Delete</strong> (and <strong>Mass Delete</strong>) remove locales, subject to the guards below.</li></ul><h2 id="delete-guards" tabindex="-1">Delete guards <a class="header-anchor" href="#delete-guards" aria-label="Permalink to &quot;Delete guards&quot;">​</a></h2><p>A locale cannot be deleted when:</p><ul><li>It is the <strong>last (only) remaining locale</strong> — the store must keep at least one.</li><li>It is the <strong>default locale of one or more channels</strong> — re-point those channels to a different default locale first.</li></ul><p>In a single delete the guard surfaces as an <code>errors[]</code> entry; in mass delete the blocked id is reported under <code>skipped</code> while the rest of the batch proceeds.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="./list.html">List locales</a></td><td><code>adminSettingsLocales</code> query</td></tr><tr><td><a href="./detail.html">Get a single locale</a></td><td><code>adminSettingsLocale(id:)</code> query</td></tr><tr><td><a href="./create.html">Create a locale</a></td><td><code>createAdminSettingsLocale</code> mutation</td></tr><tr><td><a href="./update.html">Update a locale</a></td><td><code>updateAdminSettingsLocale</code> mutation</td></tr><tr><td><a href="./delete.html">Delete a locale</a></td><td><code>deleteAdminSettingsLocale</code> mutation</td></tr><tr><td><a href="./mass-delete.html">Mass delete locales</a></td><td><code>createAdminSettingsLocaleMassDelete</code> mutation</td></tr></tbody></table><p>Permissions: <code>settings.locales.create</code> / <code>.edit</code> / <code>.delete</code>.</p>',17)]))}const g=t(l,[["render",r]]);export{p as __pageData,g as default};
